-- Write the full Marketing Virtual Assistant course.
-- Content remains draft and unpublished until practitioner review.

update public.training_courses
set estimated_minutes = 360,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    status = 'draft',
    published_at = null,
    updated_at = now()
where slug = 'marketing-virtual-assistant';

update public.training_lessons l
set content = '[{"type":"heading","text":"What marketing operations is for"},{"type":"paragraph","text":"A Marketing Virtual Assistant usually supports the movement of work from idea to approved campaign. The role is operational: organize the brief, keep the calendar current, coordinate assets and owners, prepare publishing steps, maintain campaign data, and make sure the right people see the right information at the right time."},{"type":"heading","text":"The campaign lifecycle"},{"type":"steps","items":["Objective: define the business outcome the campaign is meant to support.","Audience: identify who the campaign is for and what approved customer information exists.","Offer or message: confirm the proposition, facts, limitations, and required approvals.","Plan: map channels, assets, owners, deadlines, dependencies, and launch date.","Produce: coordinate copy, design, landing pages, email, social, forms, and tracking inputs.","Review: collect feedback, resolve conflicts, and obtain final approval.","Launch: publish the approved versions in the correct channels.","Monitor: watch delivery, links, replies, leads, obvious errors, and operational issues.","Report: prepare consistent performance data and next-step questions."]},{"type":"heading","text":"Know the difference between strategy and execution"},{"type":"paragraph","text":"Some clients may ask a VA to contribute ideas, but operational ownership is different from strategy ownership. If the client has not delegated positioning, pricing, claims, audience decisions, budget allocation, or campaign strategy to you, your job is to prepare information and execute the approved direction rather than silently invent it."},{"type":"callout","title":"Do not manufacture the brief","text":"If the campaign objective, audience, offer, deadline, or approver is unclear, do not guess. Surface the missing decision before the team spends time producing assets against the wrong brief."},{"type":"heading","text":"A useful campaign brief"},{"type":"list","items":["Campaign name and owner","Business objective","Primary audience","Approved offer or proposition","Key message","Required facts or proof points","Channels","Deliverables","Launch date","Budget or spend owner if relevant","Reviewers and final approver","Tracking requirements","Known risks or dependencies"]},{"type":"heading","text":"Build one source of truth"},{"type":"paragraph","text":"Campaign work becomes chaotic when the latest copy is in chat, the approved image is in email, the landing-page URL is in a spreadsheet, and the final launch date lives in someone''s memory. Use the client''s approved project or campaign system as the source of truth, and link out to assets rather than duplicating them everywhere."},{"type":"scenario","title":"The campaign with three launch dates","text":"The project board says Tuesday, the designer says Wednesday, and an old email says Friday. Do not choose the date that seems most convenient. Identify the current campaign owner and final approver, show the conflicting sources, and update the source of truth only after the date is confirmed."},{"type":"heading","text":"Dependencies to watch"},{"type":"list","items":["Copy cannot be finalized until the offer is approved.","Design may depend on final copy length and format.","Email may depend on a working landing page and tracking URL.","Paid or organic social may depend on approved creative and audience settings.","Sales or support may need the offer details before launch.","Reporting depends on campaign naming and tracking being correct before publication."]},{"type":"heading","text":"What strong marketing operations looks like"},{"type":"list","items":["The current brief is easy to find.","Every asset has an owner and status.","Approvals are explicit.","The final version is identifiable.","Launch dependencies are visible.","Tracking inputs are prepared before launch.","Responses and leads have a destination.","Post-launch reporting uses consistent definitions."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create a fictional campaign brief for a service business launching a new consultation offer. Include the objective, audience, approved message, five deliverables, owners, review steps, launch dependencies, and final approval point."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'how-marketing-work-moves-from-brief-to-campaign';

update public.training_lessons l
set content = '[{"type":"heading","text":"Marketing errors often start with an unverified claim"},{"type":"paragraph","text":"A polished asset can still be wrong. Marketing VAs should treat prices, product capabilities, guarantees, testimonials, statistics, dates, awards, certifications, customer counts, availability, and promotional terms as factual claims that require an approved source."},{"type":"heading","text":"Create a claim hierarchy"},{"type":"list","items":["Approved brand messaging: current language supplied by the client.","Product or service facts: maintained in the current product, service, pricing, or operations source.","Promotional terms: current campaign rules, dates, exclusions, and eligibility.","Customer proof: approved testimonials, reviews, case studies, or results.","External facts: statistics or industry claims from a reliable current source.","Draft ideas: not yet approved and not safe to publish as fact."]},{"type":"callout","title":"If the source is unclear, the claim is not ready","text":"Do not keep a statement because it ''sounds right'' or because it appeared in an old campaign. Find the current approved source or flag the claim for review."},{"type":"heading","text":"Approval stages should be visible"},{"type":"steps","items":["Draft: still being developed.","Internal review: checked by the working team.","Subject-matter review: facts or technical details checked by the right owner if required.","Legal/compliance review: used when the client requires it.","Final approval: explicitly approved for publication.","Published: the live version and URL are recorded."]},{"type":"heading","text":"Avoid approval by silence"},{"type":"paragraph","text":"Sending a file and receiving no reply is not always approval. Use the client''s defined process. For important campaigns, capture the approver, date, and approved version so the team can prove what was cleared."},{"type":"heading","text":"Brand consistency is more than colors"},{"type":"list","items":["Approved logo and usage","Type and visual style","Tone and vocabulary","Capitalization of product names","Claim language","CTA wording","Image style and permissions","Disclaimers or qualification text","Formatting rules for dates, currencies, and contact details"]},{"type":"scenario","title":"The old testimonial","text":"A designer uses a testimonial from last year''s campaign that names a customer and cites a 42% result. You cannot find current approval or the source of the number. Pause that proof point and ask the campaign owner for the approved testimonial record rather than assuming prior use makes it safe forever."},{"type":"heading","text":"Version-control habits"},{"type":"list","items":["Use one canonical asset or document link.","Name versions consistently.","Record final approval in the project system.","Do not duplicate final files into multiple folders unless the workflow requires it.","Archive or label obsolete versions clearly.","Link the live asset after publication."]},{"type":"heading","text":"Claims AI tends to get wrong"},{"type":"list","items":["Invented customer results","Unsupported superlatives such as ''best'' or ''number one''","Made-up product features","Incorrect pricing or dates","Fake citations","Fabricated testimonials","Unverified regulatory or medical statements","Outdated company information"]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Take a fictional landing-page draft with ten claims. Label each claim as approved, needs source, needs subject-matter review, or should be removed. Then list the exact source you would expect for each factual statement."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'brand-claims-approvals-and-source-of-truth';

update public.training_lessons l
set content = '[{"type":"heading","text":"A content calendar should show the work, not just the publish date"},{"type":"paragraph","text":"Many weak calendars are little more than a list of dates and titles. A useful content calendar shows what is being created, why it matters, who owns each step, what assets are required, where approval stands, and when the piece is actually ready to publish."},{"type":"heading","text":"Useful calendar fields"},{"type":"list","items":["Publish date","Channel","Topic or working title","Audience","Objective","Format","Owner","Copy status","Creative status","Review status","Final approver","Destination URL","Tracking input","Live URL"]},{"type":"heading","text":"Turn ideas into briefs"},{"type":"steps","items":["State the purpose of the content.","Define the audience.","Identify the core message.","List approved facts and source material.","Specify required format and dimensions.","Define CTA and destination.","List examples or references if useful.","State deadline, reviewer, and approver."]},{"type":"callout","title":"A brief should reduce rework","text":"If a designer or writer still has to ask what the content is for, who it is for, what the CTA is, or which claim is approved, the brief is incomplete."},{"type":"heading","text":"Track status by workflow stage"},{"type":"list","items":["Idea","Brief ready","In production","Waiting on source material","In review","Changes requested","Approved","Scheduled","Published","Repurpose or update later"]},{"type":"heading","text":"Avoid overloaded calendars"},{"type":"paragraph","text":"Do not schedule more work than the team can actually produce and review. A full calendar with half-finished assets is not a successful plan. Surface capacity constraints early and prioritize based on the approved campaign objectives."},{"type":"scenario","title":"The missing CTA","text":"A blog post is written and the graphic is complete, but nobody defined what the reader should do next. Do not invent a sales CTA. Flag the missing decision, show the available approved destinations, and get the campaign owner to confirm the intended next step."},{"type":"heading","text":"Production tracking questions"},{"type":"list","items":["What is blocked?","Who owns the next step?","What input is missing?","Which pieces are waiting on approval?","Which items are at risk of missing their publish date?","Are there channel-specific versions still needed?","Has the live destination been tested?"]},{"type":"heading","text":"Repurposing without creating junk"},{"type":"paragraph","text":"Repurposing is useful when the message still fits the channel and audience. Do not split one weak idea into ten repetitive posts just to fill the calendar. Adapt the useful part, preserve factual accuracy, and remove references that no longer make sense outside the original context."},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Build a two-week fictional content calendar with eight assets across email, social, and a website. Include ownership, review status, dependencies, CTA, destination, and one deliberate repurposing workflow."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'content-calendars-briefs-and-production-tracking';

update public.training_lessons l
set content = '[{"type":"heading","text":"Asset QA protects the campaign before the audience sees it"},{"type":"paragraph","text":"Marketing VAs often sit at the last operational checkpoint before publication. That makes quality assurance one of the highest-leverage parts of the role. The goal is not to redesign the asset. It is to catch wrong files, broken links, incorrect facts, missing approvals, bad formatting, and channel-specific mistakes."},{"type":"heading","text":"What to check in copy"},{"type":"list","items":["Names and product names","Dates and times","Prices and currencies","Promotional conditions","Spelling and grammar","CTA wording","Destination link","Approved claims","Required disclaimers","Correct audience or location"]},{"type":"heading","text":"What to check in creative"},{"type":"list","items":["Correct version","Correct dimensions","Readable text","No accidental crop of important content","Logo and brand usage","Image permission or source where required","Correct CTA and offer","No placeholder copy","No confidential data visible","File size appropriate for channel"]},{"type":"heading","text":"What to check in links and destinations"},{"type":"steps","items":["Open the final link rather than relying on the text shown.","Check desktop and mobile destination where practical.","Confirm the form works.","Confirm the CTA matches the destination.","Check query parameters or tracking inputs.","Check redirect behavior.","Check that the destination is the correct live environment.","Record the live URL after publication."]},{"type":"callout","title":"QA is not permission to rewrite strategy","text":"If the approved headline seems weak, flag it. Do not silently replace the positioning or offer just because you prefer different copy."},{"type":"scenario","title":"Everything looks right except the URL","text":"A scheduled social post uses the correct approved creative and caption, but the CTA link points to a staging page. Stop the post, replace the destination only after confirming the live URL, and re-check the final scheduled version."},{"type":"heading","text":"Use a preflight checklist"},{"type":"list","items":["Correct asset","Correct audience","Correct channel","Correct date and time","Correct link","Correct tracking","Correct approval","Correct copy","Correct offer","Correct destination"]},{"type":"heading","text":"QA failures to avoid"},{"type":"list","items":["Checking only the design file but not the scheduled post.","Testing the link from a different draft than the one being published.","Assuming a form works because the page loads.","Publishing a revised asset without confirming final approval.","Ignoring mobile cropping.","Changing approved copy during ''cleanup'' without review."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create a QA checklist for a fictional webinar campaign with a landing page, confirmation email, reminder email, three social posts, and one downloadable PDF. Include at least 20 checks across copy, creative, links, forms, tracking, approvals, and mobile presentation."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'asset-coordination-and-quality-assurance';

update public.training_lessons l
set content = '[{"type":"heading","text":"Email operations are about accuracy, consent, and timing"},{"type":"paragraph","text":"A Marketing VA may prepare campaigns, build templates, load copy, create links, schedule sends, test personalization, and report results. The role is not simply pasting copy into an email tool. Small operational mistakes can affect thousands of recipients at once."},{"type":"heading","text":"Before building the email"},{"type":"list","items":["Approved campaign brief","Approved audience or segment","Approved subject and sender identity","Approved copy","Approved CTA and destination","Required legal or preference-management elements","Send date and time","Owner and final approver"]},{"type":"heading","text":"Build checklist"},{"type":"steps","items":["Choose the correct template.","Load the approved copy.","Add links and tracking inputs.","Check personalization tokens.","Check image alt text if supported and appropriate.","Check sender name and reply address.","Check footer and preference links.","Check mobile rendering.","Send a test to the review group.","Resolve feedback before scheduling."]},{"type":"callout","title":"Do not upload random contacts to make the list bigger","text":"Respect the client''s consent, suppression, unsubscribe, and data-use rules. If you do not know whether a list is approved for marketing use, stop and ask."},{"type":"heading","text":"Personalization failure modes"},{"type":"list","items":["Missing first name resulting in awkward copy.","Wrong company field.","Old account owner inserted.","Broken conditional content.","Incorrect location or product reference.","Private CRM note accidentally used as merge content."]},{"type":"heading","text":"Pre-send test"},{"type":"list","items":["Subject and preheader","Sender and reply-to","Recipient segment","All links","Personalization","Images","Mobile view","Unsubscribe/preferences","Tracking","Schedule and time zone"]},{"type":"scenario","title":"The wrong segment","text":"The campaign is approved, but the scheduled audience contains customers who already purchased the promoted service. Do not send simply because the email itself is correct. Check the segment logic, confirm whether existing customers should be excluded, and get approval for the corrected audience."},{"type":"heading","text":"After the send"},{"type":"steps","items":["Confirm the campaign actually sent.","Check obvious delivery or rendering problems.","Route replies to the correct team.","Capture lead or response workflows.","Record campaign URL or identifier.","Prepare the reporting window agreed by the client."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Design a fictional email launch checklist from brief to post-send monitoring. Include audience approval, testing, personalization, links, mobile QA, scheduling, reply routing, and reporting."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'email-campaign-administration';

update public.training_lessons l
set content = '[{"type":"heading","text":"Marketing automation is only as reliable as the data underneath it"},{"type":"paragraph","text":"CRM segments, tags, fields, lifecycle stages, and suppression rules determine who receives which messages and how campaign performance is interpreted. A Marketing VA should understand the operational meaning of those fields before changing them."},{"type":"heading","text":"Know what each field is for"},{"type":"list","items":["Identity fields: name, email, company, role.","Source fields: where the lead or customer originated.","Lifecycle fields: lead, opportunity, customer, former customer, or client-defined stages.","Interest or product fields: what the person asked about or owns.","Consent fields: whether and how communication is allowed.","Suppression fields: do-not-contact, bounced, unsubscribed, blocked, or otherwise excluded.","Ownership fields: salesperson, account manager, or team.","Campaign fields: source campaign, last campaign, or engagement history."]},{"type":"heading","text":"Segments should be explainable"},{"type":"paragraph","text":"If you cannot explain in one or two sentences who is included and excluded, the segment logic may be too fragile. Write the rule in plain language before building it in the CRM."},{"type":"steps","items":["Define the audience in plain language.","Translate that into fields and conditions.","Add explicit exclusions.","Preview or sample the audience.","Check edge cases.","Record the segment purpose and owner.","Use the approved segment in the campaign."]},{"type":"callout","title":"Never remove unsubscribe or suppression history to improve reach","text":"A larger send count is not more important than honoring communication preferences and protecting the client''s sender reputation and compliance obligations."},{"type":"heading","text":"Common data-hygiene issues"},{"type":"list","items":["Duplicate contacts","Invalid or malformed emails","Stale company data","Tags with overlapping meanings","Free-text fields used where controlled values are needed","Lifecycle stages that were never updated","Unknown lead source","Contacts with conflicting consent or suppression fields"]},{"type":"scenario","title":"Two tags mean the same thing","text":"The CRM contains ''Webinar Lead'', ''Webinar 2026'', and ''Event Webinar'' tags for the same campaign family. Do not bulk-merge or delete them without understanding where each tag is used. Map dependencies first, propose a cleanup rule, and get approval before changing automation logic."},{"type":"heading","text":"Bulk changes require extra control"},{"type":"list","items":["Export or snapshot the affected records when the client process allows it.","Test the rule on a small sample.","Count expected records before and after.","Document the change.","Confirm automation dependencies.","Have a rollback plan for high-impact edits."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Define a fictional CRM segment for a webinar follow-up campaign. Include inclusion criteria, exclusions, consent rule, lifecycle rule, and five sample contacts showing why each person is included or excluded."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'crm-segments-tags-and-campaign-data-hygiene';

update public.training_lessons l
set content = '[{"type":"heading","text":"Launch day should be boring"},{"type":"paragraph","text":"A good launch process makes the actual publishing moment predictable. Most launch failures happen because one dependency was assumed rather than verified: the page is not live, the form goes nowhere, the email points to an old URL, the social asset is unapproved, or the sales team does not know the offer."},{"type":"heading","text":"Build a dependency map"},{"type":"list","items":["Offer and final message","Landing page","Form or checkout","Thank-you or confirmation flow","Email","Social posts","Paid campaigns if used","Sales/support briefing","Tracking","Reporting owner"]},{"type":"heading","text":"Pre-launch checkpoint"},{"type":"steps","items":["Confirm final approval.","Confirm the landing destination is live.","Test the form or conversion path.","Check campaign tracking inputs.","Check every scheduled asset against the final brief.","Check time zones and launch timing.","Confirm lead routing.","Confirm internal teams know the campaign is launching.","Identify the person who can pause the campaign if something breaks."]},{"type":"callout","title":"Never launch around a broken conversion path","text":"If the campaign CTA leads to a broken form, checkout, booking page, or wrong offer, stop the affected channel until the destination is corrected. Traffic is not useful if the next step fails."},{"type":"heading","text":"Cross-channel consistency"},{"type":"list","items":["Same offer and eligibility rules","Same campaign dates","Same pricing unless intentionally channel-specific","Same core message","Correct destination","Correct brand assets","Correct tracking naming","No contradictory CTA"]},{"type":"scenario","title":"Email is ready but the page is not","text":"The email is scheduled for 9:00 AM, but the landing page still shows placeholder copy at 8:40 AM. Pause or reschedule the email according to authority, notify the campaign owner, and do not send traffic to a knowingly incomplete destination just to preserve the original send time."},{"type":"heading","text":"Launch monitoring"},{"type":"list","items":["Page loads","Form or checkout submits","Confirmation works","Email sends","Scheduled posts publish","Links resolve","Leads arrive in the expected system","Customer questions are routed","No obvious tracking or offer mismatch"]},{"type":"heading","text":"Post-launch handoff"},{"type":"steps","items":["Record what went live.","Link the live assets.","Record any issue and fix.","Confirm lead routing.","Confirm who owns replies.","Set the first reporting checkpoint."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create a launch checklist for a fictional downloadable-guide campaign using a landing page, form, email, three social posts, sales follow-up, and analytics tracking. Include stop-launch conditions."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'campaign-launch-checklists-and-cross-channel-coordination';

update public.training_lessons l
set content = '[{"type":"heading","text":"Every response needs an owner"},{"type":"paragraph","text":"Campaigns generate replies, comments, direct messages, form submissions, questions, complaints, sales leads, partnership requests, job enquiries, and spam. Marketing operations should define where each type goes before launch so customer messages do not disappear in channel inboxes."},{"type":"heading","text":"Create a routing matrix"},{"type":"list","items":["Sales enquiry → sales or business development","Existing customer issue → support or account team","Billing question → finance or billing","Press or media → designated communications owner","Partnership request → partnerships or founder","Job enquiry → recruiting","Complaint → support or escalation owner","Legal/privacy request → authorized specialist","Routine public comment → approved community-management process"]},{"type":"heading","text":"Capture context before routing"},{"type":"steps","items":["Who contacted the business?","Which campaign or post did they respond to?","What are they asking?","Is there a deadline or urgency?","What has already been said?","Which owner should receive it?","What follow-up is required?"]},{"type":"callout","title":"Routing is not dumping","text":"Forwarding a screenshot with ''FYI'' is weak handoff. Give the next owner enough context to understand the request, what was already communicated, and what action is expected."},{"type":"heading","text":"Lead routing"},{"type":"list","items":["Capture the original source.","Create or update the CRM record.","Preserve the person''s message.","Assign the correct owner.","Create the next action.","Avoid scoring or qualification decisions outside the approved process.","Keep response-time expectations visible."]},{"type":"scenario","title":"A comment becomes a sales lead","text":"Someone comments on a campaign post asking whether the service supports a specific workflow. If the answer is approved and routine, respond according to the client''s rules. If the question affects fit, pricing, or commitments, capture the lead and route it to the correct owner rather than improvising a sales answer publicly."},{"type":"heading","text":"Complaints and sensitive replies"},{"type":"list","items":["Do not argue.","Do not delete criticism simply because it is negative unless it violates the client''s moderation policy.","Acknowledge where approved.","Move account-specific details to a private channel.","Escalate threats, legal issues, privacy concerns, discrimination claims, safety issues, or serious reputational matters.","Document what was said and what action was taken."]},{"type":"heading","text":"Response-time operations"},{"type":"paragraph","text":"Different messages deserve different response expectations. A serious customer complaint or high-intent sales lead may require faster routing than a general comment. Use the client''s service standards rather than treating every notification as urgent."},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create a routing table for ten fictional campaign responses across sales, support, complaints, partnerships, job enquiries, billing, privacy, and general comments. Define the owner, expected response time, and required CRM or ticket update."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'community-lead-and-response-routing';

update public.training_lessons l
set content = '[{"type":"heading","text":"Reporting should describe what happened before explaining why"},{"type":"paragraph","text":"Marketing reports become unreliable when observed data and interpretation are mixed together. A Marketing VA should be able to prepare accurate campaign metrics, note important changes, and identify useful questions without claiming causation that the data does not prove."},{"type":"heading","text":"Start with the funnel the campaign actually uses"},{"type":"list","items":["Reach or delivery","Views or impressions","Clicks or visits","Leads or sign-ups","Qualified actions if defined","Bookings, purchases, or other business outcomes","Cost where relevant"]},{"type":"heading","text":"Define every metric"},{"type":"paragraph","text":"A ''lead'' might mean a form submission in one company and a sales-qualified record in another. A ''conversion'' might mean a download, booked call, or purchase. Use the client''s definitions and keep them consistent across reporting periods."},{"type":"steps","items":["Confirm date range.","Confirm channel and campaign filters.","Pull data from the approved source.","Check whether totals reconcile with platform or CRM records.","Calculate only agreed metrics.","Compare against the correct prior period or benchmark.","Separate observed changes from possible explanations.","List questions or next actions."]},{"type":"callout","title":"Correlation is not automatically causation","text":"If clicks rose after a new headline launched, you can report that both happened. Do not state that the headline caused the increase unless the test design or evidence supports that conclusion."},{"type":"heading","text":"Common metrics to understand"},{"type":"list","items":["Open or delivery metrics where the platform provides them","Click-through rate","Landing-page conversion rate","Cost per click","Cost per lead","Lead-to-booking rate","Purchase conversion rate","Revenue attribution as defined by the client","Unsubscribe or complaint rate","Organic reach or engagement where relevant"]},{"type":"scenario","title":"More leads, worse business result","text":"Campaign B generated 200 leads versus Campaign A''s 120, but the CRM shows fewer qualified calls from Campaign B. Do not report Campaign B as the clear winner based only on lead volume. Present the downstream conversion and ask whether lead quality or targeting changed."},{"type":"heading","text":"Reporting integrity"},{"type":"list","items":["Do not change date ranges to make results look better.","Do not remove weak channels without disclosure.","Do not combine different definitions under one metric.","Do not claim attribution the system cannot support.","Flag missing or duplicated data.","Use notes for campaign changes that affect comparison."]},{"type":"heading","text":"Executive-friendly summary"},{"type":"steps","items":["What happened.","What materially changed.","Where the biggest drop-off or improvement occurred.","What is still uncertain.","What should be checked next."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create a fictional one-page report for a lead-generation campaign using impressions, clicks, landing-page visits, form submissions, booked calls, and spend. Write three observations and three questions without inventing causal explanations."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'marketing-reporting-and-basic-performance-interpretation';

update public.training_lessons l
set content = '[{"type":"heading","text":"AI is useful for acceleration, not authority"},{"type":"paragraph","text":"Marketing teams can use AI to brainstorm angles, summarize approved source material, restructure copy, produce first drafts, generate variants, organize research notes, and speed up repetitive work. The risk begins when generated output is treated as factual, approved, compliant, or brand-safe without review."},{"type":"heading","text":"Good uses for AI"},{"type":"list","items":["Generate first-draft outlines from approved briefs.","Create copy variants from verified source material.","Summarize long internal documents where data handling is approved.","Suggest content repurposing formats.","Organize campaign notes.","Draft QA checklists.","Generate questions for a research brief.","Rewrite approved copy for clarity while preserving facts."]},{"type":"heading","text":"High-risk uses"},{"type":"list","items":["Uploading confidential customer lists or internal financial data to an unapproved tool.","Generating testimonials or customer results.","Creating legal, medical, financial, or regulatory claims without expert review.","Inventing statistics or sources.","Generating product capabilities from memory.","Publishing AI output directly without human review.","Using synthetic images or voices in ways that mislead the audience."]},{"type":"callout","title":"The final responsibility stays with the team","text":"A model does not approve the campaign. Verify facts, protect client data, follow brand rules, and route specialist claims to the appropriate reviewer."},{"type":"heading","text":"A safe AI workflow"},{"type":"steps","items":["Use an approved tool.","Remove confidential or unnecessary personal information.","Provide verified source material.","Ask for a draft, not a ''fact''.","Check every factual statement.","Check tone and brand fit.","Check for unsupported claims.","Record approval before publication."]},{"type":"heading","text":"AI slop signals"},{"type":"list","items":["Generic claims that could describe any business.","Repeated three-item rhetorical patterns.","Empty phrases such as ''unlock your potential'' or ''elevate your brand'' without substance.","Made-up certainty.","Overuse of adjectives instead of proof.","Fake quotes or statistics.","Long copy that says little.","Tone that does not sound like the client."]},{"type":"scenario","title":"The AI-generated case study","text":"A draft generated from sparse notes says the client ''increased revenue by 35% in three months''. That number is not in the source material. Remove the claim, check the approved case-study data, and never keep a number because it makes the story stronger."},{"type":"heading","text":"AI and customer data"},{"type":"paragraph","text":"Do not paste private CRM records, support tickets, contracts, medical information, credentials, unreleased product information, or other sensitive data into a model unless the client has explicitly approved that workflow and the tool is appropriate for the data."},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Take a fictional AI-generated campaign draft containing eight claims. Mark which parts are safe as stylistic drafts, which require source verification, which require specialist review, and which should be deleted entirely."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'responsible-ai-in-marketing-operations';

update public.training_lessons l
set content = '[{"type":"heading","text":"Marketing work crosses team boundaries"},{"type":"paragraph","text":"A Marketing VA may work between a client, agency account manager, designer, writer, developer, media buyer, sales team, support team, founder, and external vendor. The handoff quality determines whether work moves smoothly or disappears into chat."},{"type":"heading","text":"Every handoff needs six things"},{"type":"list","items":["What is being handed off.","Current status.","What has already been approved.","What remains unresolved.","Next owner.","Deadline or next checkpoint."]},{"type":"heading","text":"Handoff examples"},{"type":"list","items":["Copy to design: final approved copy, dimensions, CTA, destination, due date.","Design to campaign manager: approved assets, variants, source files, notes, publishing deadline.","Campaign to sales: offer, audience, lead source, follow-up expectation, launch date.","Campaign to support: expected questions, offer terms, escalation route.","Agency to client: status, decisions needed, approvals, risks, next milestone."]},{"type":"callout","title":"Do not hand off uncertainty as if it were settled","text":"If the offer date, price, claim, or final asset is still under review, make that status explicit. The next team should not discover unresolved decisions after launch."},{"type":"heading","text":"Agency-specific risks"},{"type":"list","items":["Working from a client comment that was not final approval.","Losing feedback across email, chat, and project tools.","Mixing assets between clients.","Using the wrong brand template.","Missing scope boundaries.","Publishing before the account lead confirms client approval."]},{"type":"heading","text":"In-house risks"},{"type":"list","items":["Assuming everyone saw the campaign because they share the same company.","Launching before sales or support understands the offer.","Using internal shorthand in customer-facing copy.","Skipping formal approvals because the team sits close together.","Failing to document decisions because they happened verbally."]},{"type":"scenario","title":"The designer says approved, the client says not yet","text":"The project board shows the graphic as approved because the designer finished revisions, but the client has not confirmed the final version. Do not treat production completion as client approval. Update the status accurately and keep the asset out of the publishing queue until the required approval exists."},{"type":"heading","text":"A strong marketing handoff note"},{"type":"steps","items":["Campaign and asset.","Current version.","Approved facts and copy.","Open decision.","Owner.","Deadline.","Source links.","Next action."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Write four fictional handoffs: copy to design, design to publishing, marketing to sales, and agency to client. Each should contain only the information the next owner actually needs."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'agency-and-in-house-handoffs';

update public.training_lessons l
set content = '[{"type":"heading","text":"Final practice: coordinate a marketing campaign"},{"type":"paragraph","text":"This simulation combines briefing, content operations, QA, email, CRM data, launch coordination, response routing, reporting, and responsible AI use. Every company, customer, result, and campaign in the exercise is fictional."},{"type":"heading","text":"Scenario background"},{"type":"paragraph","text":"You support a small B2B services company launching a free consultation campaign. The campaign includes a landing page, email, three social posts, a downloadable checklist, CRM lead routing, and a small paid promotion. The founder approves claims and offers, a designer owns creative, sales owns lead qualification, and support owns existing-customer issues."},{"type":"heading","text":"Incoming issues"},{"type":"list","items":["The approved brief says the campaign launches Thursday, but an old spreadsheet says Wednesday.","One social graphic uses an outdated price.","The email test contains a broken booking link.","The CRM segment includes existing customers even though the campaign is for new prospects.","A generated draft claims the company has helped ''more than 5,000 businesses'', but there is no approved source.","The landing-page form submits successfully, but the lead is assigned to the wrong sales owner.","A customer comments publicly that they are unhappy with an existing service issue.","The founder asks for a launch update in 15 minutes.","After launch, clicks rise but booked calls do not.","The agency designer says an asset is ''final'', but there is no client approval recorded."]},{"type":"heading","text":"Part 1: Prioritise"},{"type":"steps","items":["Rank the ten issues by launch risk and customer impact.","Mark which issues block launch.","Mark which can be fixed independently within normal admin authority.","Mark which need founder, sales, support, design, or another owner.","Identify the AI-generated claim that must not be published without verification."]},{"type":"heading","text":"Part 2: Produce the work"},{"type":"list","items":["Write the campaign-status update for the founder.","Create the corrected pre-launch checklist.","Write the escalation note for the outdated price asset.","Document the broken-link fix and final QA step.","Define the corrected CRM segment in plain language.","Write the lead-routing correction note.","Route the existing-customer complaint correctly.","Write the approval-status note for the designer''s ''final'' asset.","Create a short post-launch report explaining the click-to-booking drop-off without inventing a cause."]},{"type":"callout","title":"Assessment standard","text":"You are assessed on accuracy, launch judgment, source discipline, approval control, customer routing, CRM hygiene, reporting integrity, and whether you avoid publishing unsupported claims or AI-generated fiction."},{"type":"heading","text":"Part 3: Self-review"},{"type":"list","items":["Did you identify every launch blocker?","Did you distinguish production completion from final approval?","Did you fix the audience logic before sending?","Did you avoid inventing a reason for the conversion drop?","Did you route the customer complaint outside marketing when appropriate?","Did you remove or verify the unsupported AI claim?","Did every unresolved item have an owner and next action?"]},{"type":"heading","text":"What excellent work looks like"},{"type":"paragraph","text":"Excellent Marketing VA work is operationally disciplined. The campaign source of truth is current, approvals are visible, customer data is handled carefully, the conversion path works, responses reach the correct team, and reporting separates what the data shows from what the team still needs to investigate."},{"type":"scenario","title":"Optional stretch scenario","text":"The founder asks you to publish the campaign immediately even though the booking link is still failing. Explain how you would communicate the risk, what you would pause, what could continue safely, and what proof you would need before resuming the affected channel."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'marketing-virtual-assistant'
  and l.slug = 'composite-marketing-va-work-simulation';

update public.training_assessments
set instructions = 'Complete the composite Marketing VA work simulation from the final lesson and submit: (1) a prioritized launch-risk list, (2) a founder campaign-status update, (3) a corrected pre-launch checklist, (4) an outdated-price asset escalation, (5) a broken-link QA record, (6) a corrected CRM segment definition, (7) a lead-routing correction note, (8) a customer-complaint routing note, (9) an approval-status handoff for the final creative, and (10) a short post-launch performance report that separates observed data from assumptions. Review should assess factual accuracy, approval discipline, source control, launch judgment, data hygiene, customer routing, reporting integrity, and responsible AI use. The learner must not publish unsupported claims, invent approvals, override consent or suppression rules, or state causal conclusions that the data does not support.',
    assessment_type = 'practical',
    pass_score = null,
    is_published = false,
    updated_at = now()
where course_id = (select id from public.training_courses where slug='marketing-virtual-assistant');
